def json_differences(a,b,p=''):
    if type(a)!=type(b):return [p]
    if isinstance(a,dict):
        out=[]
        for k in sorted(set(a)|set(b)):
            q=p+'/'+str(k).replace('~','~0').replace('/','~1')
            out.extend([q] if k not in a or k not in b else json_differences(a[k],b[k],q))
        return out
    if isinstance(a,list):
        if len(a)!=len(b):return [p]
        return [q for i,(x,y) in enumerate(zip(a,b)) for q in json_differences(x,y,p+'/'+str(i))]
    return [] if a==b else [p]

